import {S,term as T,step as P,check as Q,task as A,lesson as L} from './shared.js';
export default [
L(3,1,{
 title:'预训练到底在学什么：从原文构造监督',summary:'先做出可检查的训练样本，再讨论数据配比。通过一条完整文本认识预训练和自监督。',prerequisites:['w2-l3','w1-l3'],
 terms:[T('预训练 pretraining','为模型建立较通用基础能力的一段训练过程；具体目标仍要明确。','语言模型常从大量文本学习前缀到下一 token 的预测。'),T('自监督 self-supervised','目标从数据自身构造，而不是每一项都由人另写标签。','句子后面的词可以成为前面内容的预测目标，仍然有明确监督。'),T('持续预训练','从已有模型权重出发，继续用预训练类目标学习新数据。','在现成语言模型上继续训练领域文本。'),T('数据配比 data mixture','不同数据来源在实际训练消费中所占的比例，必须说明计量单位。','按条数各一半，不代表按 token 数各一半。')],
 sections:[P('第 1 步：把预训练从“大量数据”还原成一次更新','第二周的前缀预测提供输入和目标，第一周的训练过程提供更新方法。把这两条线连接起来：文本编码，构造前缀目标，网络预测候选分数，计算损失，再更新参数；重复很多次就组成训练。','预训练不是神奇的额外步骤，也不必从第一天就使用海量数据。小模型也能做预训练实验，但不能因此期待它拥有大模型的通用能力。'),P('第 2 步：没有人工标签也可以有目标','假设原文是“机器人向左移动”。即使没有人给每个位置再标答案，下一个 token 已经在原文里。这就是自监督目标的一个例子。原文的收集、清洗和质量判断仍可能包含大量人工工作。','从已有权重继续学习同类目标叫持续预训练。使用问答示范来改变遵循指令的行为则在第 5 周详细学习；当前只按原文组织目标，不提前要求你实现指令微调。'),P('第 3 步：先分组，再切窗口','先按完整文档、视频或轨迹划分训练与验证，再在各组内部切片。文本窗口可以重叠，但不能让同一原始文档的近重复片段同时出现在两边，除非评测目的明确允许。','写数据卡：每条样本的来源、原始对象 ID、清洗规则、分词器版本、长度、目标生成规则。遇到异常 loss 时，这些字段让你能定位是哪类样本造成的。'),P('第 4 步：计算实际被学习的数据量','短数据 100 条、每条 20 token；长数据 100 条、每条 200 token。按条数是 50:50，按 token 是 2000:20000。模型主要接触了长数据中的预测目标。','训练日志应记录实际消费的有效 token，而不只是数据池总量。采样、补齐、截断和损失遮挡都可能改变有效监督；输入很多不等于每个位置都参与学习。'),P('第 5 步：从一批数据开始运行','下载训练包后先打开 tiny_lm.py，找到 corpus、编码和输入/目标切片所在位置。这个教学模型使用合成短句，优点是规模小、可检查；缺点是不能用它的成绩代表真实语言理解。','先打印一条样本的原文、编号、输入、目标，确认对齐后再运行 40 步。任何训练命令前，先知道损失来自哪些位置，是数据工程经验转化成算法能力的重要一步。')],
 worked:{title:'同一批数据的两种配比',steps:['短来源：100×20=2000 个 token。','长来源：100×200=20000 个 token。','总数 22000；短来源占约 9.1%，长来源占约 90.9%。','声明“各占一半”必须补上“按条数”；否则别人无法复现实验。'],takeaway:'比较配比时先确定样本、token、有效目标还是计算预算。'},
 example:{code:'sources = {"short": (100, 20), "long": (100, 200)}\ntotal = sum(count*length for count,length in sources.values())\nfor name,(count,length) in sources.items():\n    print(name, "tokens", count*length, "fraction", round(count*length/total, 3))',output:'short tokens 2000 fraction 0.091\nlong tokens 20000 fraction 0.909',explanation:'这里没有 padding 和目标遮挡；真实训练要进一步统计有效监督量。'},
 checks:[Q('自监督是否意味着没有标准目标、也没有 loss？','回想下一 token 在哪里。','不是。目标从原文自身得到，仍需通过损失比较预测和目标。',1),Q('为何先切片再随机划分，可能高估模型对新文档的能力？','检查两边是否来自同一个原始对象。','高度相似的重叠片段可能跨集合，评测没有真正检验新对象上的能力。',2)],
 practice:{title:'做一张可追溯的数据卡',steps:[A('下载训练包，阅读 tiny_lm.py 中的合成语料和划分逻辑。','能说出数据来自模板，不是真实互联网语料。','先查 README 的运行说明，浏览器 Python 不包含 PyTorch。'),A('手工展开一条样本的输入与目标。','能够逐位置对应下一 token。','如果目标和当前输入完全一样，检查是否遗漏了右移。'),A('记录来源比例的条数口径与 token 口径。','一份表里明确两种单位；后续对照固定同一口径。','不要用数据集条数代替实际消费量。')]},links:[{label:'下载本地训练包',href:'./downloads/model-craft-labs.zip'}],sources:[S.cs336,S.hf]
}),
L(3,2,{
 title:'从分数到损失：训练设置怎样影响学习',summary:'用三个候选词计算概率和交叉熵，再逐项理解学习率、优化器和模型参数量。',prerequisites:['w3-l1','w1-l2'],
 terms:[T('logits','模型输出的未归一化候选分数，可以为负，也不要求和为 1。','三个候选词分数 [2,1,0] 需要转换后才是概率。'),T('交叉熵 cross entropy','分类训练里常用的损失；对单一正确类别，可理解为正确答案概率的负对数。','正确答案概率从 0.2 升到 0.8，损失从约 1.61 降到约 0.22。'),T('loss mask 损失掩码','逐位置指定是否把这一项误差计入训练目标；它与控制输入可见性的注意力掩码不同。','两项真实目标的损失为 2、4，另有两个 PAD；有效平均为 (2+4)/2=3，而不是除以四。'),T('AdamW','利用历史梯度统计调整更新，并将权重衰减与梯度更新分开的优化算法。','它负责怎么更新参数，不改变数据里的目标答案。'),T('warmup 与梯度裁剪','warmup 让学习率从小逐步增加；裁剪限制一次过大的梯度范数。','它们是更新控制手段，不能修好错位的标签。'),T('PPL 困惑度','语言模型中常用 exp(平均 token 交叉熵) 表示的指标。','比较前要固定分词器、数据和有效监督位置。')],
 sections:[P('第 1 步：让模型给多个候选打分','数值回归只输出一个数字；文字预测要在词表里选择下一个 token。模型先输出 V 个 logits，再经 softmax 得到概率。用分数而不是直接输出离散编号，可以为学习提供连续变化的信息。','计算 softmax 时先减去最大分数，再做指数和归一化。这个平移不改变概率，却避免 exp(1000) 之类的溢出。'),P('第 2 步：只关注正确答案获得了多少概率','如果目标是第一个候选，loss=−log(p_first)。概率越接近 1，损失越接近 0；给错误候选很高概率时，正确目标概率会更低，损失更大。使用自然对数。','PyTorch CrossEntropyLoss 接收 logits 并在内部处理稳定计算，不要先 softmax 后当 logits 再传入。多个有效位置的损失按约定平均；PAD 应被排除，避免把大量补齐当成训练内容。这用 loss mask 指定计分位置，并按有效位置数量取平均；PAD 编号恰好为 0 不代表损失函数会自动忽略它。'),P('第 3 步：优化器和学习率各做什么','第一周用纯梯度下降。AdamW 还维护梯度的一阶、二阶统计，让不同参数的更新尺度自适应；weight decay 则对权重施加衰减。它增加了需保存的优化器状态。','warmup 用于训练起步阶段逐步提高学习率，之后可以衰减。裁剪只限制梯度规模，不会知道标签是否正确。先把目标、掩码和数值计算检查清楚，再讨论调学习率。'),P('第 4 步：控制参数规模与显存','增加层数、隐藏维度、前馈宽度或词表，会改变参数量；简单统计所有可训练数组的元素数即可。冻结某个模块意味着不更新它，但计算中仍可能使用其权重。','训练显存还保存梯度、优化器状态和中间激活。序列更长、batch 更大，通常增加激活开销，即使参数量完全不变。不要把模型文件大小当作训练所需显存。'),P('第 5 步：运行一个可比较的基线','按照训练包 README 安装 PyTorch，执行 python tiny_lm.py --steps 40 --device cpu --log-every 20。保存更新前的验证 loss，以及训练后的同一项指标。输出乱码在这个小预算下不奇怪，先看学习链路是否正常。','再用相同 seed、相同数据和步数比较另一学习率。seed 是随机数种子的设置；记录它能控制部分随机变化，但不保证不同硬件的结果逐位一致。')],
 worked:{title:'三个候选词的概率和损失',steps:['分数为 [2,1,0]，减最大值得到 [0,−1,−2]。','指数化约为 [1,0.368,0.135]，归一化后约为 [0.665,0.245,0.090]。','目标为第一个候选时，loss=−log(0.665)≈0.408。','若把正确候选分数提高，在其余分数不变时，正确概率增大，loss 下降。'],takeaway:'网络输出分数，损失提供学习信号，采样才把分布变成一个具体选择。'},
 example:{code:'import math\nlogits = [2.0, 1.0, 0.0]\nshifted = [x-max(logits) for x in logits]\nweights = [math.exp(x) for x in shifted]\nprobs = [x/sum(weights) for x in weights]\nloss = -math.log(probs[0])\nprint([round(p, 3) for p in probs])\nprint("loss", round(loss, 3))',output:'[0.665, 0.245, 0.09]\nloss 0.408',explanation:'只有这里的演示代码显式计算概率；调用 PyTorch 交叉熵时应直接传 logits。'},
 checks:[Q('把全部 logits 同时加 100，会改变 softmax 概率吗？','观察减去最大值后的结果。','不会，共同平移会抵消。实现不稳定时可能溢出，但那是数值问题。',0),Q('把输入长度从 128 改到 256，是否必然增加参数量？','回到词表和权重矩阵的形状。','不必然；若结构和词表不变，参数数量不变，但中间计算、激活和注意力开销可能增加。',3)],
 practice:{title:'先理解目标，再调一个训练设置',steps:[A('完成稳定交叉熵代码练习，测试极大分数。','结果保持有限，正确答案概率越高时损失越低。','先减最大值，必要时使用 log-sum-exp 形式。'),A('按 README 在 CPU 跑 tiny_lm.py 的 40 步基线。','日志包含参数量、验证 loss、PPL 和生成样例。','提示 No module named torch 时，在运行脚本的同一个虚拟环境安装 requirements。'),A('只改变 --learning-rate，保持 seed 和 steps 不变。','可以比较同预算下的验证结果，而非只看最后一批训练 loss。','保存两次完整命令，别依赖记忆。')]},links:[{label:'稳定交叉熵练习',href:'#/code/stable-cross-entropy'},{label:'本地训练运行说明',href:'./downloads/README.md'}],sources:[S.ce,S.adam,S.cs336]
}),
L(3,3,{
 title:'训练存档与恢复：保存了权重，还缺什么',summary:'用一次“中断再继续”的故事，区分模型文件、完整训练状态和公平比较。',prerequisites:['w3-l2'],
 terms:[T('checkpoint 检查点','在某个训练时刻保存的状态集合，内容取决于实现。','可能只有权重，也可能包括优化器、步数和数据位置。'),T('initialize 初始化','选择一次新实验的参数起点。','从旧模型权重开始，但重置训练步数和优化器，属于新实验。'),T('resume 续训','尝试从中断时的训练状态继续。','除了权重，还要恢复该步的学习率、优化器统计和数据消费位置。'),T('验证协议','固定数据、预处理、指标和生成规则的一套评测约定。','比较两个检查点时，不能一边用贪心、一边随机挑最好输出。')],
 sections:[P('第 1 步：把训练想成一个有状态的程序','第 3 周的模型参数只是状态的一部分。AdamW 保存历史梯度统计，学习率调度器保存进度，数据加载器需要知道哪些样本已经被消费。训练中断时，这些状态都可能影响下一步。','所以“文件能加载”只证明文件格式与当前模型相容，不证明训练能够沿原路线继续。先看保存函数到底写入了哪些键。'),P('第 2 步：区分三种起点','fresh 表示新建模型并初始化权重；initialize 表示读取已有权重来启动新的训练；resume 表示读取足够的训练状态继续旧实验。这些词是实验约定，具体项目可能使用不同参数名。','从第 1000 步权重开始却把调度器归零，会再次经历 warmup。若本来想续训，这可能是错误；若有意开始新的适应实验，则可以合理，但应在报告里明确。'),P('第 3 步：列一张恢复核对表','至少检查模型参数、优化器状态、学习率调度状态、更新步数、随机数状态和数据位置。带记忆的序列模型还可能涉及运行状态，后续第 9 周再展开。','检查是否恢复了“下一次该读的数据”，不能只看 step 数一致。多进程加载、预取和数据打乱都会使精确恢复更复杂，本周先在简单单进程例子里理解必要条件。'),P('第 4 步：比较时固定观察窗口','每隔若干步用同一份验证集计算 loss；固定少量生成样例帮助肉眼观察。固定样例只是补充，不代表总体。不能每次随机挑一条最好看的结果作为提升依据。','训练包 tiny_lm.py 可保存检查点和指标，但没有提供 --resume 命令。不要凭文件存在就假设它支持完整续训。本周先检查保存字段，后续实现恢复时再做连续训练与中断恢复的对照。')],
 worked:{title:'为什么两次“从第 1000 步开始”并不等价',steps:['实验 A：加载权重、优化器、调度器、step=1000 和下一个数据位置。','实验 B：只加载相同权重，优化器统计和学习率进度从头开始。','两者第一次前向可能相同，第一次更新却可能不同。','A 可用于验证续训，B 应标记为从旧权重初始化的新实验。'],takeaway:'存档是什么，需要看字段；能恢复到什么程度，需要对照实验。'},
 example:{code:'required = {"model", "optimizer", "scheduler", "step", "rng", "data_position"}\nweights_only = {"model": "weights"}\nfull_example = {key: "example value" for key in required}\nprint("missing", sorted(required - weights_only.keys()))\nprint("complete keys", required <= full_example.keys())',output:"missing ['data_position', 'optimizer', 'rng', 'scheduler', 'step']\ncomplete keys True",explanation:'这是字段检查，不是可直接恢复训练的真实检查点。字段齐全也需要验证内容正确、恢复逻辑生效。'},
 checks:[Q('只加载权重，再换数据和优化器，应该叫完整续训吗？','比较是否保留旧训练的更新过程。','应标记为从旧权重初始化的新实验，不能称为精确恢复原训练。',1),Q('十条固定样例看起来都变好了，可以替代整个验证集吗？','十条样例的覆盖范围是什么？','不能。它们适合观察具体变化，但可能遗漏其他数据类型和失败模式。',3)],
 practice:{title:'审查自己的第一个模型文件',steps:[A('查看 tiny_lm.py 的保存部分，列出实际保存字段。','把已保存、未保存和没有实现的恢复动作分开记录。','脚本没有 --resume，不能照搬不存在的命令。'),A('给两次学习率实验保留独立目录和配置。','不会用同一个文件名覆盖另一份证据。','使用不同 --output 路径，具体参数格式见 README。'),A('写出将来验证续训正确性的对照。','连续训练 N 步，与训练 K 步保存恢复再到 N 步比较。','比较学习率、数据位置和更新后参数，不只比较日志步数。')]},sources:[S.checkpoint,S.repro]
})];
